def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Report_Categories.csv'
    # Try common encodings due to smart quotes
    for enc in ['utf-8', 'cp1252', 'latin1']:
        try:
            df = pd.read_csv(path, header=None, encoding=enc)
            df['__encoding__'] = enc
            return pd.concat([df.head(8), df.tail(8)], ignore_index=True)
        except UnicodeDecodeError:
            continue
    # fallback
    df = pd.read_csv(path, header=None, encoding='latin1')
    df['__encoding__'] = 'latin1'
    return pd.concat([df.head(8), df.tail(8)], ignore_index=True)
